('duyufuna-cache-setting', 'O:18:\"App\\Models\\Setting\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:8:\"settings\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:89:{s:2:\"id\";i:1;s:4:\"logo\";s:54:\"settings/6LKAECp0CQRlRTwFMAEFWLjpEJzuvHaAHUvxDVEC.webp\";s:7:\"favicon\";s:53:\"settings/JES8f7juDQDiQsMEIM2CUgjwMYvjaNzNApTbdgtX.png\";s:8:\"og_image\";N;s:8:\"og_title\";N;s:14:\"og_description\";N;s:7:\"og_type\";N;s:12:\"og_site_name\";N;s:12:\"twitter_card\";N;s:13:\"twitter_title\";N;s:19:\"twitter_description\";N;s:13:\"twitter_image\";N;s:13:\"canonical_url\";N;s:6:\"robots\";s:13:\"index, follow\";s:24:\"google_site_verification\";N;s:22:\"bing_site_verification\";N;s:19:\"google_analytics_id\";N;s:21:\"google_tag_manager_id\";N;s:14:\"schema_enabled\";i:0;s:8:\"org_name\";N;s:8:\"org_logo\";N;s:9:\"org_phone\";N;s:9:\"org_email\";N;s:11:\"org_address\";N;s:11:\"org_geo_lat\";N;s:11:\"org_geo_lng\";N;s:15:\"sitemap_enabled\";i:1;s:12:\"banner_image\";s:54:\"settings/Nm83LXikUFXN8w9TOEF9s8ubuODNOhMTyzmZHDNM.webp\";s:12:\"banner_badge\";N;s:12:\"banner_title\";N;s:15:\"banner_cta_text\";N;s:14:\"banner_cta_url\";N;s:13:\"hero_subtitle\";s:4:\"Halo\";s:14:\"greeting_image\";s:54:\"settings/aDkXS8czm0NiRg7UBZ7XhbgNkygLpl1g0xDMDrVN.webp\";s:14:\"greeting_title\";s:16:\"Assalamu\'alaikum\";s:17:\"greeting_subtitle\";s:26:\"Selamat datang di Duyufuna\";s:13:\"greeting_text\";s:135:\"Temukan berbagai layanan umroh dan haji untuk menemani perjalanan ibadah Anda dengan lebih mudah, nyaman, dan tenang menuju Tanah Suci.\";s:9:\"why_label\";N;s:9:\"why_title\";N;s:12:\"why_subtitle\";N;s:12:\"about_banner\";s:53:\"settings/CEKjxYpkH4cmweb57wPUlWFagAp95PVeMr2CDDQZ.jpg\";s:11:\"about_image\";s:54:\"settings/Hb985l3DWV3dUoHMM1cYnavXuErjEStvdzK3KSKW.webp\";s:11:\"about_title\";s:45:\"DUYUFUNA - Pelayanan Umroh & Haji Profesional\";s:10:\"about_body\";s:2091:\"<h2>Tentang Kami<br><br></h2><p class=\"isSelectedEnd\">Duyufuna hadir sebagai penyedia layanan umroh dan haji yang berkomitmen membantu memenuhi berbagai kebutuhan perjalanan jamaah menuju Tanah Suci. Kami memahami bahwa perjalanan ibadah bukan sekadar perjalanan biasa, tetapi sebuah perjalanan yang membutuhkan persiapan, ketelitian, kenyamanan, dan pelayanan yang baik sejak sebelum keberangkatan hingga jamaah kembali ke tanah air.<br><br></p><p class=\"isSelectedEnd\">Melalui berbagai layanan yang terintegrasi, kami menyediakan kebutuhan pendukung perjalanan seperti pengurusan visa, akomodasi hotel di Mekkah, Madinah, dan Jeddah, transportasi, handling bandara, handling hotel, catering, laundry, serta berbagai kebutuhan lainnya. Setiap layanan disiapkan untuk membantu jamaah maupun penyelenggara perjalanan mendapatkan solusi yang lebih praktis dan terkoordinasi.</p><p class=\"isSelectedEnd\">Kami terus berupaya menghadirkan pelayanan yang responsif, fleksibel, dan berorientasi pada kebutuhan jamaah. Dengan memahami bahwa setiap rombongan memiliki kebutuhan yang berbeda, layanan dapat disesuaikan berdasarkan jumlah jamaah, jadwal perjalanan, pilihan akomodasi, serta kebutuhan khusus lainnya.<br><br></p><h3>Visi</h3><p class=\"isSelectedEnd\">Menjadi penyedia layanan umroh dan haji yang terpercaya dan profesional dalam menghadirkan kemudahan, kenyamanan, serta layanan pendukung perjalanan ibadah yang berkualitas bagi setiap jamaah.<br><br></p><h3>Misi</h3><ul data-spread=\"false\"><li>Menyediakan berbagai layanan pendukung perjalanan umroh dan haji secara lengkap dan terintegrasi.</li><li>Memberikan pelayanan yang mudah, responsif, dan sesuai dengan kebutuhan jamaah.</li><li>Mengutamakan kenyamanan, ketepatan, dan kualitas dalam setiap layanan.</li><li>Membangun kerja sama yang baik dengan berbagai pihak untuk mendukung kelancaran perjalanan jamaah.</li><li>Terus meningkatkan kualitas layanan dan mengikuti perkembangan kebutuhan perjalanan ibadah.</li><li>Membantu menciptakan perjalanan menuju Tanah Suci yang lebih tertata, nyaman, dan tenang bagi jamaah.</li></ul>\";s:18:\"trust_badge_1_icon\";N;s:18:\"trust_badge_1_text\";N;s:18:\"trust_badge_2_icon\";N;s:18:\"trust_badge_2_text\";N;s:18:\"trust_badge_3_icon\";N;s:18:\"trust_badge_3_text\";N;s:18:\"trust_badge_4_icon\";N;s:18:\"trust_badge_4_text\";N;s:17:\"testimonial_label\";N;s:17:\"testimonial_title\";N;s:20:\"testimonial_subtitle\";N;s:8:\"cta_pill\";N;s:9:\"cta_title\";N;s:12:\"cta_subtitle\";N;s:10:\"cta_button\";N;s:19:\"services_page_title\";N;s:22:\"services_page_subtitle\";N;s:17:\"galeri_page_title\";N;s:20:\"galeri_page_subtitle\";N;s:20:\"testimoni_page_title\";N;s:23:\"testimoni_page_subtitle\";N;s:14:\"faq_page_title\";N;s:17:\"faq_page_subtitle\";N;s:18:\"artikel_page_title\";N;s:21:\"artikel_page_subtitle\";N;s:12:\"website_name\";s:8:\"DUYUFUNA\";s:7:\"tagline\";s:33:\"MELAYANI TAMU ALLAH, SEPENUH HATI\";s:8:\"whatsapp\";N;s:10:\"wa_message\";N;s:5:\"email\";s:17:\"info@duyufuna.com\";s:7:\"address\";s:17:\"Jepara, Indonesia\";s:11:\"footer_text\";s:136:\"<p>Layanan perjalanan umroh dan haji yang membantu setiap langkah perjalanan menuju Tanah Suci dengan mudah, nyaman, dan terpercaya.</p>\";s:22:\"footer_contact_heading\";N;s:20:\"footer_links_heading\";N;s:12:\"footer_links\";N;s:16:\"footer_copyright\";s:16:\"© 2026 DUYUFUNA\";s:9:\"seo_title\";s:42:\"DUYUFUNA - Layanan Umroh & Haji Terpercaya\";s:15:\"seo_description\";s:91:\"Platform layanan umroh, haji, hotel, dan transportasi di tanah suci. Mudah, amanah, berkah.\";s:12:\"seo_keywords\";s:54:\"umroh, haji, travel umroh, hotel mekkah, hotel madinah\";s:16:\"social_instagram\";N;s:15:\"social_facebook\";N;s:14:\"social_youtube\";N;s:13:\"social_tiktok\";N;s:10:\"created_at\";s:19:\"2026-07-28 11:43:27\";s:10:\"updat