INSERT INTO `categories` (`id`, `name`, `slug`, `icon`, `subtitle`, `whatsapp`, `wa_message`, `sort`, `is_catalog`, `group_label`, `item_label`, `description`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
(1, 'Hotel', 'hotel', '🏨', NULL, NULL, NULL, 1, 1, 'Kota', 'Hotel', '<p>Pilihan hotel terbaik di Mekkah, Madinah, dan Jeddah untuk kenyamanan ibadah Anda.</p>', 'Hotel Umroh Mekkah Madinah Jeddah', 'Pilih hotel terbaik di area Masjidil Haram, Masjid Nabawi, dan Jeddah untuk perjalanan umroh Anda.', 'hotel umroh, hotel mekkah, hotel madinah, hotel jeddah', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(2, 'Visa', 'visa', '📋', NULL, NULL, NULL, 2, 1, 'Jenis', 'Visa', '<p>Pengurusan visa umroh yang cepat, aman, dan terpercaya.</p>', 'Visa Umroh', 'Pengurusan visa umroh cepat dan terpercaya.', 'visa umroh, paspor umroh, syarat visa', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(3, 'Transportasi', 'transportasi', '🚐', NULL, NULL, NULL, 3, 0, NULL, NULL, '<p>Armada transportasi nyaman untuk seluruh rute perjalanan umroh Anda.</p>', 'Transportasi Umroh', 'Sewa transportasi umroh dengan armada nyaman dan terpercaya.', 'transportasi umroh, sewa bus umroh, travel umroh', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(4, 'Handling Bandara', 'handling-bandara', '✈️', NULL, NULL, NULL, 4, 0, NULL, NULL, '<p>Layanan handling bandara kedatangan dan kepulangan yang profesional.</p>', 'Handling Bandara Umroh', 'Layanan handling bandara kedatangan dan kepulangan untuk jamaah umroh.', 'handling bandara, portir umroh, jemput bandara', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(5, 'Handling Hotel', 'handling-hotel', '🛎️', NULL, NULL, NULL, 5, 0, NULL, NULL, '<p>Layanan handling hotel check-in dan check-out agar perjalanan Anda lebih praktis.</p>', 'Handling Hotel Umroh', 'Layanan handling hotel check-in dan check-out untuk jamaah umroh.', 'handling hotel, check in umroh, check out umroh', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(7, 'Laundry', 'laundry', '👕', NULL, NULL, NULL, 7, 0, NULL, NULL, '<p>Layanan laundry cepat, bersih, dan wangi selama di Tanah Suci.</p>', 'Laundry Umroh', 'Layanan laundry untuk jamaah umroh dengan hasil bersih dan wangi.', 'laundry umroh, laundry mekkah, laundry madinah', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(8, 'Buggy Car', 'buggy-car', '🚗', NULL, NULL, NULL, 8, 0, NULL, NULL, '<p>Layanan buggy car untuk mobilitas jamaah di sekitar Masjidil Haram.</p>', 'Buggy Car Umroh', 'Sewa buggy car untuk mobilitas jamaah di area Masjidil Haram.', 'buggy car umroh, buggy mekkah', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(9, 'Jastip Viral', 'jastip-viral', '🛍️', NULL, NULL, NULL, 9, 1, 'Produk', 'Produk', '<p>Layanan titip belanja berbagai produk populer dari Arab Saudi untuk jamaah yang ingin membawa oleh-oleh atau memenuhi permintaan keluarga dan kerabat di Indonesia.</p>', 'Jastip Viral Tanah Suci', 'Jastip oleh-oleh viral dan kekinian dari Tanah Suci.', 'jastip viral, jastip mekkah, oleh oleh umroh', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(11, 'Fotografer', 'fotografer', '📸', NULL, NULL, NULL, 11, 0, NULL, NULL, '<p>Fotografer profesional untuk mendokumentasikan momen ibadah Anda.</p>', 'Fotografer Umroh', 'Fotografer profesional untuk dokumentasi kegiatan umroh Anda.', 'fotografer umroh, foto umroh', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(12, 'Penukaran Uang', 'penukaran-uang', '💵', NULL, NULL, NULL, 12, 0, NULL, NULL, '<p>Penukaran uang dengan kurs terbaik dan terpercaya.</p>', 'Penukaran Uang Umroh', 'Penukaran uang Riyal dengan kurs terbaik dan terpercaya.', 'penukaran uang, money changer umroh', '2026-07-28 05:53:02', '2026-08-14 06:49:45'),
(14, 'Catering', 'catering', '🍽️', NULL, NULL, NULL, 6, 1, 'Paket', 'Paket', '<p>Catering halal berkualitas untuk kedatangan dan kepulangan jamaah.</p>', 'Catering Umroh', 'Catering halal untuk kedatangan dan kepulangan jamaah umroh dengan menu pilihan.', 'catering umroh, paket makan, katering bandara', '2026-07-29 05:22:43', '2026-08-14 06:49:45'),
(15, 'Kursi Roda Umroh', 'kursi-roda-umroh', '♿', NULL, NULL, NULL, 10, 0, NULL, NULL, '<p>Sewa kursi roda untuk jamaah lansia dan berkebutuhan khusus.</p>', 'Sewa Kursi Roda Umroh', 'Sewa kursi roda untuk jamaah umroh lansia dan berkebutuhan khusus.', 'kursi roda umroh, sewa kursi roda mekkah', '2026-07-29 05:22:43', '2026-08-14 06:49:45'),
(16, 'Muthawif', 'muthawif', '🕋', NULL, NULL, NULL, 13, 0, NULL, NULL, '<p>Muthawif berpengalaman sebagai pembimbing ibadah selama di Tanah Suci.</p>', 'Muthawif Umroh', 'Muthawif berpengalaman sebagai pembimbing ibadah jamaah umroh.', 'muthawif, pembimbing ibadah umroh', '2026-07-31 18:53:43', '2026-08-14 06:49:45');
