INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `image`, `short_description`, `description`, `requirement`, `information`, `benefit`, `price`, `duration`, `icon`, `meta_title`, `meta_description`, `meta_keywords`, `whatsapp`, `wa_message`, `status`, `created_at`, `updated_at`) VALUES
(86, 1, 'Mekkah', 'mekkah', 'services/QxXjN6NCL0HWfPzbZFLix18NdXSztDXHD4BQD2aW.jpeg', 'Pilihan hotel di Mekkah yang strategis dan nyaman untuk jamaah umroh maupun haji, dengan fokus utama pada kedekatan ke Masjidil Haram, kemudahan akses ibadah, dan kenyamanan jamaah.', '<p><strong>Pilihan hotel:</strong> Fairmont Makkah Clock Royal Tower, Swiss&ocirc;tel Al Maqam Makkah, Pullman ZamZam Makkah, Hilton Suites Makkah, Anjum Hotel Makkah, Jabal Omar Marriott Hotel Makkah, Emaar Grand Hotel Makkah.</p>', NULL, NULL, NULL, NULL, NULL, '🏨', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:49:45'),
(87, 1, 'Madinah', 'madinah', 'services/sikBInuXzGjKV9TMKDesq026Ql3wZGfGXxbphTzz.jpg', 'Pilihan hotel di Madinah yang berada di lokasi strategis dekat Masjid Nabawi, sehingga memudahkan jamaah untuk melaksanakan ibadah, ziarah, dan beraktivitas selama berada di Madinah.', '<p><strong>Pilihan hotel:</strong> Anwar Al Madinah M&ouml;venpick, Madinah Hilton, Pullman Zamzam Madina, Dar Al Taqwa, Sofitel Shahd Al Madinah, Dallah Taibah, Elaf Al Taqwa, Al Manakha Rotana Madinah.</p>', NULL, NULL, NULL, NULL, NULL, '🕌', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:49:45'),
(88, 1, 'Jeddah', 'jeddah', 'services/zD7whmNtECKGwiECIp1yJs6sBOzOXHSBWBmZVE7b.jpeg', 'Pilihan hotel di Jeddah yang nyaman dan strategis, terutama untuk transit jamaah, akses menuju Bandara King Abdulaziz, serta perjalanan menuju Mekkah dan Madinah.', '<p><strong>Pilihan hotel:</strong> Crowne Plaza Jeddah Al Salam, Clarion Hotel Jeddah Airport, Best Western Plus Jeddah Hotel Madinah Road, Jeddah Marriott Hotel Madinah Road, Radisson Blu Hotel Jeddah Al Salam, Jeddah Hilton, InterContinental Jeddah, Aerotel Jeddah.</p>', NULL, NULL, NULL, NULL, NULL, '🌆', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:49:45'),
(89, 2, 'Visa Umroh', 'visa-umroh', 'services/W2xvvKohJ4DKXHo102ffFjXCpyuDEogtUfDkejbn.jpeg', 'Layanan pengurusan visa untuk membantu mempersiapkan dokumen perjalanan jamaah menuju Tanah Suci dengan lebih mudah dan terarah.', '<p>Layanan pengurusan visa untuk membantu jamaah mempersiapkan dokumen perjalanan menuju Arab Saudi. Proses pengajuan dilakukan sesuai persyaratan dan ketentuan visa yang berlaku, dengan pilihan layanan berdasarkan kebutuhan dan durasi perjalanan jamaah.</p>', NULL, NULL, NULL, NULL, NULL, '📋', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:49:45'),
(90, 3, 'Transportasi Bandara', 'transportasi-bandara', 'services/2dC5nWwpDcxaAAMQCzaBm6svZpRq4FLsjwiO7wXB.jpeg', 'Transportasi nyaman untuk perjalanan jamaah dalam jumlah besar.', '<p>Bus pariwisata menjadi pilihan ideal untuk rombongan jamaah yang membutuhkan perjalanan bersama dengan kapasitas penumpang yang besar. Kendaraan digunakan untuk perjalanan antar kota seperti Jeddah, Mekkah, dan Madinah maupun kebutuhan transportasi selama program umroh. Dengan ruang yang lebih luas dan fasilitas perjalanan yang nyaman, perjalanan rombongan dapat berlangsung lebih teratur dan efisien.</p>', NULL, NULL, NULL, 150000.00, NULL, '🚌', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 14:04:28'),
(91, 3, 'Coaster', 'coaster', 'services/4TJR7Dfy9tDikyWABcewtVMmG7yn72VfyV5nBgix.jpeg', 'Kendaraan berkapasitas menengah untuk perjalanan jamaah yang lebih fleksibel.', '<p>Coaster menjadi alternatif antara kendaraan kecil dan bus pariwisata dengan kapasitas penumpang yang lebih besar. Kendaraan ini sesuai untuk rombongan menengah yang membutuhkan kenyamanan sekaligus fleksibilitas dalam perjalanan. Dapat digunakan untuk perjalanan Jeddah&ndash;Mekkah&ndash;Madinah maupun kebutuhan transportasi lokal selama berada di Tanah Suci.</p>', NULL, NULL, NULL, 3500000.00, NULL, '🚌', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:49:45'),
(92, 3, 'Toyota Hiace', 'toyota-hiace', 'services/VobrKwUohWzBVeRIKXhqRISFzj6uy669tFGHjfn9.jpeg', 'Pilihan praktis untuk keluarga dan rombongan kecil.', '<p>Kendaraan jenis Hiace cocok digunakan untuk jamaah dalam kelompok kecil yang menginginkan perjalanan lebih fleksibel dan nyaman. Ukurannya yang lebih ringkas memudahkan perjalanan di berbagai rute perkotaan, sementara kapasitasnya cukup untuk membawa beberapa jamaah sekaligus beserta perlengkapan perjalanan. Cocok untuk perjalanan keluarga, rombongan kecil, maupun kebutuhan transportasi khusus.</p>', NULL, NULL, NULL, 1800000.00, NULL, '🚐', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 14:05:43'),
(93, 4, 'Kedatangan', 'kedatangan', 'services/mbGuuZmyDR6qA0eEO6u8LziXQyw8XqfIZjeOC95o.jpg', 'Layanan penyambutan & handling saat kedatangan', '<p>Pendampingan jamaah saat tiba di bandara Indonesia setelah menyelesaikan perjalanan umroh atau haji. Tim membantu mengarahkan jamaah menuju area pengambilan bagasi, titik penjemputan, hingga memastikan jamaah dan barang bawaan dapat melanjutkan perjalanan dengan tertib.</p>', NULL, NULL, NULL, NULL, NULL, '🛬', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:07:25'),
(94, 4, 'Kepulangan', 'kepulangan', 'services/TUZqvx9ut2aSdO7PGtVjAAJb3IzNhJVANSKiUpAe.jpeg', 'Layanan handling saat kepulangan', '<p>Pendampingan jamaah di bandara Indonesia untuk membantu proses setelah perjalanan ibadah selesai, sehingga jamaah dapat menuju area kedatangan dan penjemputan dengan lebih terarah dan nyaman.</p>', NULL, NULL, NULL, NULL, NULL, '🛫', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:08:10'),
(95, 5, 'Check In', 'check-in', 'services/VqfzjYUbeaSu6WikqigiTzfxC0AZO3U2VongWqzu.jpg', 'Handling check-in hotel, kunci & proses kamar diuruskan', '<p>Pendampingan jamaah saat memasuki hotel untuk membantu proses registrasi, pembagian kamar, serta koordinasi barang bawaan. Layanan ini membantu rombongan agar proses check-in dapat berlangsung lebih teratur tanpa membuat jamaah harus mengurus seluruh proses secara mandiri.</p>', NULL, NULL, NULL, NULL, NULL, '🔑', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:10:15'),
(96, 5, 'Check Out', 'check-out', 'services/2VdZEPePFjEL0F8xnwtWeNrSKq45wMDy90paubby.jpeg', 'Handling check-out hotel, bagasi & proses diuruskan', '<p>Pendampingan jamaah saat meninggalkan hotel untuk memastikan proses check-out, pengumpulan barang, dan persiapan keberangkatan berjalan dengan tertib. Tim membantu mengoordinasikan jamaah dan bagasi sebelum menuju kendaraan atau lokasi perjalanan berikutnya.</p>', NULL, NULL, NULL, NULL, NULL, '🧳', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:10:59'),
(97, 14, 'Kedatangan', 'kedatangan-2', 'services/WTGPzZeDqoChLFOEfe0QAsoiIlhwyCR4GKgEse1d.jpeg', 'Catering saat kedatangan bandara', '<p>Layanan catering kedatangan disiapkan untuk memberikan konsumsi kepada jamaah setelah menyelesaikan perjalanan ibadah. Makanan dikemas secara praktis sehingga mudah dibagikan kepada jamaah di titik kedatangan, area penjemputan, maupun lokasi yang telah ditentukan. Menu dapat disesuaikan dengan kebutuhan dan jumlah jamaah.</p>', NULL, NULL, NULL, NULL, NULL, '🛬', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:32:15'),
(98, 14, 'Kepulangan', 'kepulangan-2', 'services/XCp2WlrQmJucayuHPSgxSfbvXIBEHOBgcykb4OGM.jpeg', 'Konsumsi praktis untuk menemani jamaah sebelum melanjutkan perjalanan menuju Tanah Suci.', '<p>Layanan catering kepulangan disiapkan untuk memenuhi kebutuhan konsumsi jamaah sebelum atau selama perjalanan menuju bandara. Menu dikemas secara praktis dan mudah dibawa sehingga jamaah tetap dapat menikmati makanan tanpa mengganggu proses persiapan keberangkatan. Penyediaan makanan dapat disesuaikan dengan jadwal penerbangan, jumlah jamaah, dan kebutuhan rombongan.</p>', NULL, NULL, NULL, NULL, NULL, '🛫', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 16:33:28'),
(99, 7, 'Laundry Kilat', 'laundry-kilat', 'services/laundry-kilat-jNcBmb.jpg', 'Layanan laundry kilat, bersih & wangi', NULL, NULL, NULL, NULL, 50000.00, NULL, '👕', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-06 23:56:33'),
(100, 8, 'Buggy Car Area Haram', 'buggy-car-haram', 'services/buggy-car-area-haram-IkM6cs.jpg', 'Antar-jemput buggy di sekitar Masjidil Haram', NULL, NULL, NULL, NULL, 75000.00, NULL, '🚗', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-06 23:56:36'),
(105, 15, 'Sewa Kursi Roda', 'kursi-roda-sewa', 'services/sewa-kursi-roda-mfGxVJ.jpg', 'Sewa kursi roda untuk jamaah lansia / berkebutuhan khusus', NULL, NULL, NULL, NULL, 100000.00, NULL, '♿', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-06 23:56:47'),
(109, 12, 'Penukaran Riyal', 'penukaran-riyal', 'services/penukaran-riyal-RUb5dh.jpg', 'Penukaran uang Riyal Saudi dengan rate terbaik', NULL, NULL, NULL, NULL, NULL, NULL, '💵', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-06 23:56:57'),
(110, 16, 'Muthawif Per Hari', 'muthawif-per-hari', 'services/muthawif-per-hari-ptoSuz.jpg', 'Pembimbing ibadah muthawif selama di Tanah Suci', NULL, NULL, NULL, NULL, 250000.00, NULL, '🕋', NULL, NULL, NULL, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-06 23:57:00'),
(115, 9, 'Oleh-Oleh Khas Arab Saudi', 'oleh-oleh-khas-arab-saudi', 'services/HJqI67ldw6L1eAGUWnlOF4JaSWddITJepWo4BXdD.jpeg', 'Berbagai oleh-oleh khas Tanah Suci yang populer dibawa pulang oleh jamaah.', '<p>Berbagai oleh-oleh khas Tanah Suci yang populer dibawa pulang oleh jamaah.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-08-07 18:17:59', '2026-08-07 18:35:05'),
(119, 9, 'Oleh-Oleh Islami', 'oleh-oleh-islami', 'services/KbgvVwwMfb48H2IMFtd2lfvgpor55cdnVd4oSgoC.jpeg', 'Pilihan perlengkapan dan cendera mata bernuansa Islami dari Tanah Suci.', '<p>Pilihan perlengkapan dan cendera mata bernuansa Islami dari Tanah Suci.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-08-07 18:39:20', '2026-08-14 06:49:45'),
(120, 9, 'Produk Viral & Populer', 'produk-viral-populer', 'services/yFzRM5Oo3TyRaAhFQY7IwlTyPjujYHaBUdosLSUz.jpg', 'Membantu mendapatkan berbagai produk yang sedang populer dan banyak dicari dari Arab Saudi.', '<p>Membantu mendapatkan berbagai produk yang sedang populer dan banyak dicari dari Arab Saudi.</p>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-08-07 18:42:43', '2026-08-07 18:42:43');
INSERT INTO `service_items` (`id`, `service_id`, `title`, `image`, `description`, `sort`, `whatsapp`, `wa_message`, `status`, `created_at`, `updated_at`) VALUES
(122, 86, 'Makkah Clock Royal Tower - A Fairmont Hotel', 'service-items/ftuGiqJ7gTfJfl0T5P0ogE6YJA0zfr3mtOzQ6Fx6.jpeg', '<p>Salah satu pilihan paling premium di Makkah. Hotel berada di kompleks Abraj Al Bait yang langsung bersebelahan dengan Masjidil Haram.</p>', 1, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-07 05:57:42'),
(123, 86, 'Pullman ZamZam Makkah', 'service-items/eMM5OTTYHMFKSbSvpQIp9YsP5wy5sRXx3sLnqLn8.jpeg', '<ul><li>Berada di kompleks Abraj Al Bait\r</li><li>Sangat dekat dengan Masjidil Haram\r</li><li>Cocok untuk keluarga\r</li><li>Banyak pilihan kamar untuk jamaah\r</li><li>Sangat cocok untuk paket <strong>premium dan VIP</strong></li></ul>', 2, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:55:20'),
(124, 86, 'Hilton Suites Jabal Omar Makkah', 'service-items/iN0COftoJwgEoA6TPmZBKUPDoDdhhUXZSMyyeOSS.jpg', '<p>Pilihan yang sangat menarik untuk <strong>keluarga dan rombongan</strong>.</p><ul>\r\n<li>Hotel modern\r</li><li>Kamar relatif luas\r</li><li>Lokasi Jabal Omar\r</li><li>Akses ke Masjidil Haram cukup dekat\r</li><li>Cocok untuk jamaah keluarga</li></ul>', 3, NULL, NULL, 1, '2026-08-05 03:03:36', '2026-08-14 06:55:20'),
(125, 87, 'Madinah Hilton', 'service-items/OA5HJPHWnE08PI5UmVcXm2n5zE5NWcw416YTlozc.jpeg', '<ul><li>Sekitar 2 menit berjalan kaki dari Masjid Nabawi.</li><li>Sangat dekat dengan Gate 25, yang memudahkan akses jamaah wanita.</li><li>Sebagian kamar memiliki pemandangan kota maupun area Haram.</li><li>Cocok untuk keluarga dan jamaah lansia.</li></ul>', 1, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(126, 87, 'Pullman Zamzam Madina', 'service-items/tc3eTn3loDRYu6yr2CUJHjGGrP6M2xdZnxPgWzjI.jpeg', '<ul><li>Berada sangat dekat dengan Masjid Nabawi.\r</li><li>Sekitar <strong>2 menit</strong> berjalan kaki menurut beberapa panduan hotel.\r</li><li>Memiliki ratusan kamar dan suite sehingga cocok untuk <strong>rombongan besar</strong>.\r</li><li>Fasilitas hotel cukup lengka</li></ul>', 2, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(127, 87, 'Dar Al-Taqwa Hotel', 'service-items/WzZcRNgE55pSRg9lg74Q2c3n7W6hfgUOYCWRMuhb.jpeg', '<ul><li>Sangat dekat dengan Masjid Nabawi.\r</li><li>Pilihan kelas premium.\r</li><li>Cocok untuk jamaah yang mengutamakan <strong>kenyamanan dan akses ibadah</strong>.</li></ul>', 3, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(128, 88, 'Crowne Plaza Jeddah Al Salam', 'service-items/7FeEcxYrdTQN7BImJUxYNmX7p33wYgwFONaKJXhi.jpg', '<ul><li>Kawasan Al-Muhammadiyah.\r</li><li>Dekat King Abdulaziz International Airport.\r</li><li>Cocok untuk <strong>transit jamaah sebelum menuju Makkah</strong>.\r</li><li>Cocok untuk rombongan keluarga maupun grup umrah.</li></ul>', 1, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(129, 88, 'Best Western Plus Jeddah Hotel Madinah Road', 'service-items/8IIamezYNOHd1puWCKL8dRyKuXuFBoMef3QPtWRO.jpeg', '<ul><li>Berada di Madinah Road.\r</li><li>Relatif dekat dengan bandara.\r</li><li>Cocok untuk paket umrah kelas menengah.</li></ul>', 2, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(130, 88, 'Clarion Hotel Jeddah Airport', 'service-items/yiqFiZYJS85qblGRoNceqzExaAfwO2kCO3G4bsJF.jpeg', '<ul><li>Berada di kawasan Al Marwah.\r</li><li>Akses relatif mudah menuju bandara.\r</li><li>Cocok untuk jamaah yang hanya menginap <strong>1 malam</strong>.</li></ul>', 3, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-14 06:55:20'),
(136, 97, 'Nasi Box', 'service-items/j2jUMUMgGNHM9ZQ7pwlpPxcQz2pwOyhqdmdUqhzN.jpeg', '<p>Paket makanan lengkap dalam kemasan praktis yang terdiri dari nasi, lauk, sayuran, dan pelengkap. Cocok untuk konsumsi jamaah setelah tiba di Indonesia.</p>', 1, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-07 16:34:50'),
(137, 97, 'Snack Box', 'service-items/MzIysxkevAftx4aW13V8mKtWjP0VpVelKbRhGPPv.jpeg', '<p>Paket makanan ringan yang berisi pilihan kue, makanan ringan, dan minuman. Praktis untuk diberikan kepada jamaah sebagai makanan pendamping setelah perjalanan panjang.</p>', 2, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-07 16:35:57'),
(139, 98, 'Nasi Box Perjalanan', 'service-items/zu7wdAghqwa7VFkzi5KeFnLcb6U66xjgOMiQblDP.jpeg', '<p>Paket makanan lengkap yang dikemas praktis untuk dibawa selama perjalanan menuju bandara atau titik keberangkatan.</p>', 1, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-07 16:37:10'),
(140, 98, 'Snack Perjalanan', 'service-items/OgjK4f8WjXDDuqNMbkYifzJJr4wXeZSrZtCV9jdr.jpeg', '<p>Paket makanan ringan yang praktis dibawa dan dikonsumsi jamaah selama perjalanan menuju bandara maupun saat menunggu keberangkatan.</p>', 2, NULL, NULL, 1, '2026-08-05 03:03:37', '2026-08-07 16:38:05'),
(157, 89, 'Visa 30 Hari', 'service-items/xBzE9PQnViP5IqJpM1qHRa6KwmDPZtfjJRZC7M3I.jpeg', '<p>Visa Umroh untuk perjalanan dengan masa tinggal hingga 30 hari, sesuai dengan ketentuan visa yang diterbitkan. Pilihan ini cocok bagi jamaah yang memiliki itinerary umroh singkat, seperti perjalanan Mekkah dan Madinah dalam satu rangkaian. Pengurusan mencakup proses pengajuan dan pemeriksaan dokumen yang diperlukan sebelum visa diterbitkan</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-14 06:55:20'),
(158, 89, 'Visa 60 Hari', 'service-items/8HyicSYTLGKVPp0MZU50chkqmnmfuWCMgaf2FYO0.jpeg', '<p>Pilihan visa untuk jamaah yang membutuhkan waktu perjalanan lebih panjang, hingga 60 hari apabila jenis visa dan ketentuan yang berlaku mengizinkannya. Durasi tinggal tidak semata-mata ditentukan oleh permintaan pemohon, tetapi mengikuti masa berlaku dan ketentuan yang tercantum pada visa yang diterbitkan. Karena aturan visa dapat berubah berdasarkan musim dan kebijakan pemerintah Arab Saudi, masa tinggal akhir perlu dikonfirmasi saat pengajuan.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-14 06:55:20'),
(159, 89, 'Visa Perpanjangan', 'service-items/8ZVQo7lIZR7AA9shdIOYDGb7zbIP9HI0gyiOSJ16.jpeg', '<p>Layanan bantuan untuk kebutuhan perpanjangan atau penyesuaian masa tinggal visa, apabila jenis visa yang dimiliki dan ketentuan imigrasi Arab Saudi memungkinkan perpanjangan. Setiap permohonan akan disesuaikan dengan status visa, masa berlaku, jenis visa, serta kebijakan yang berlaku pada saat pengajuan. Perpanjangan tidak otomatis tersedia untuk semua jenis visa, sehingga status dan kelayakannya perlu diperiksa terlebih dahulu.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-14 06:55:20'),
(160, 99, 'Cuci Reguler', 'service-items/laundry-kilat-cuci-reguler-GvY7cq.jpg', '<p>Pilihan Cuci Reguler dari Laundry Kilat yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:19'),
(161, 99, 'Setrika Express', 'service-items/laundry-kilat-setrika-express-2JkkkD.jpg', '<p>Pilihan Setrika Express dari Laundry Kilat yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:19'),
(162, 99, 'Laundry Harian', 'service-items/laundry-kilat-laundry-harian-J7REb0.jpg', '<p>Pilihan Laundry Harian dari Laundry Kilat yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:22'),
(163, 100, 'Sewa Harian', 'service-items/buggy-car-area-haram-sewa-harian-Iwb0js.jpg', '<p>Pilihan Sewa Harian dari Buggy Car Area Haram yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:22'),
(164, 100, 'Sewa Paket Per Jam', 'service-items/buggy-car-area-haram-sewa-paket-per-jam-shBd1r.jpg', '<p>Pilihan Sewa Paket Per Jam dari Buggy Car Area Haram yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:23'),
(165, 100, 'Buggy VIP', 'service-items/buggy-car-area-haram-buggy-vip-TtM5j2.jpg', '<p>Pilihan Buggy VIP dari Buggy Car Area Haram yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:01', '2026-08-06 23:57:23'),
(166, 105, 'Kursi Roda Reguler', 'service-items/sewa-kursi-roda-kursi-roda-reguler-FxL9oE.jpg', '<p>Pilihan Kursi Roda Reguler dari Sewa Kursi Roda yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:37'),
(167, 105, 'Kursi Motor Wheelchair', 'service-items/sewa-kursi-roda-kursi-motor-wheelchair-yhGnAo.jpg', '<p>Pilihan Kursi Motor Wheelchair dari Sewa Kursi Roda yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:42'),
(168, 105, 'Kursi Roda Premium', 'service-items/sewa-kursi-roda-kursi-roda-premium-WC4vMx.jpg', '<p>Pilihan Kursi Roda Premium dari Sewa Kursi Roda yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:42'),
(169, 109, 'Riyal Cash', 'service-items/penukaran-riyal-riyal-cash-2Pyrw8.jpg', '<p>Pilihan Riyal Cash dari Penukaran Riyal yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:43'),
(170, 109, 'Dolar ke Riyal', 'service-items/penukaran-riyal-dolar-ke-riyal-ty7kEn.jpg', '<p>Pilihan Dolar ke Riyal dari Penukaran Riyal yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:43'),
(171, 109, 'Kirim Uang', 'service-items/penukaran-riyal-kirim-uang-sikExS.jpg', '<p>Pilihan Kirim Uang dari Penukaran Riyal yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:44'),
(172, 110, 'Pendampingan Harian', 'service-items/muthawif-per-hari-pendampingan-harian-eek4Vb.jpg', '<p>Pilihan Pendampingan Harian dari Muthawif Per Hari yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 1, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:44'),
(173, 110, 'Pendamping Ziarah', 'service-items/muthawif-per-hari-pendamping-ziarah-u2qiWn.jpg', '<p>Pilihan Pendamping Ziarah dari Muthawif Per Hari yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 2, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:47'),
(174, 110, 'Pendamping Manasik', 'service-items/muthawif-per-hari-pendamping-manasik-VbQxvC.jpg', '<p>Pilihan Pendamping Manasik dari Muthawif Per Hari yang nyaman dan terpercaya untuk perjalanan ibadah Anda.</p>', 3, NULL, NULL, 1, '2026-08-06 23:53:02', '2026-08-06 23:57:50'),
(175, 86, 'Swissôtel Makkah', 'service-items/TEKxG8Lx2owRyXkS2x4vgQpBeBAIs5tmVK2xkvM8.jpeg', '<p>Salah satu hotel yang menurut saya sangat cocok untuk <strong>paket umrah premium Indonesia</strong>.</p><ul><li>Berada di kompleks Abraj Al Bait\r</li><li>Sangat dekat dengan Masjidil Haram\r</li><li>Sebagian kamar memiliki pemandangan Ka\'bah\r</li><li>Akses relatif mudah</li></ul>', 4, NULL, NULL, 1, '2026-08-07 06:05:35', '2026-08-14 06:55:20'),
(200, 115, 'Kurma Ajwa', 'service-items/61V6QGrhcibQvwtD8Xph1cldXBYraip0P55n2j7r.jpg', '<p>Kurma Ajwa dari Madinah yang menjadi salah satu oleh-oleh favorit jamaah untuk dibawa pulang sebagai buah tangan bagi keluarga dan kerabat.</p>', 1, NULL, NULL, 1, '2026-08-07 18:36:27', '2026-08-07 18:36:49'),
(201, 115, 'Kurma Premium', 'service-items/DBt6ZjVWOgTIvT1qSfVYvHqdrdNZbib0HoQ1icyi.jpeg', '<p>Pilihan berbagai jenis kurma berkualitas dari Arab Saudi dengan kemasan yang cocok untuk oleh-oleh.</p>', 2, NULL, NULL, 1, '2026-08-07 18:37:24', '2026-08-07 18:37:41'),
(202, 115, 'Cokelat Arab', 'service-items/W61c1VBG3vQ2G3cayc6b5SiVXd7y8FeEfhKt6Ltn.jpeg', '<p>Beragam cokelat khas dan populer di Arab Saudi yang dapat menjadi pilihan oleh-oleh praktis untuk keluarga maupun rekan kerja.</p>', 3, NULL, NULL, 1, '2026-08-07 18:38:12', '2026-08-07 18:38:30'),
(203, 119, 'Tasbih', 'service-items/hMfwWrPDSK2WcTIB55lWTnv8BI0s8sYuyQiE1Fdd.jpeg', '<p>Tasbih dengan berbagai pilihan bahan, warna, dan model yang cocok sebagai oleh-oleh untuk keluarga maupun kerabat.</p>', 1, NULL, NULL, 1, '2026-08-07 18:39:58', '2026-08-07 18:40:11'),
(204, 119, 'Sajadah', 'service-items/HpOOvY8YiHmcGz0JOlffZIVpROChj1nsHkpSc9PD.jpeg', '<p>Sajadah dengan beragam motif dan kualitas yang dapat dipilih sebagai buah tangan dari perjalanan ke Tanah Suci.</p>', 2, NULL, NULL, 1, '2026-08-07 18:40:42', '2026-08-07 18:41:01'),
(205, 119, 'Parfum Non-Alkohol', 'service-items/Wn0DJvqamd1WLd7ZpcDgO4nk5Do9DWdIjLsrBoYa.jpeg', '<p>Pilihan parfum dan wewangian khas Timur Tengah yang populer sebagai oleh-oleh, dengan beragam aroma dan ukuran.</p>', 3, NULL, NULL, 1, '2026-08-07 18:41:34', '2026-08-07 18:41:49'),
(206, 120, 'Camilan & Makanan Populer', 'service-items/9Hqk7Q7agJPP6J7oQhGJQmGlOry7vzK5AQF3VbXB.jpeg', '<p>Berbagai camilan, makanan ringan, dan produk makanan populer yang dapat dititipkan sesuai ketersediaan dan ketentuan pengiriman.</p>', 1, NULL, NULL, 1, '2026-08-07 18:43:23', '2026-08-07 18:43:23'),
(207, 120, 'Produk Khas Madinah', 'service-items/yYbj7eA4uaxxaeIcjR84n5oX30js6dWKNXv1cgnl.jpg', '<p>Pilihan produk khas Madinah yang banyak diminati jamaah sebagai oleh-oleh dan buah tangan untuk keluarga di Indonesia.</p>', 2, NULL, NULL, 1, '2026-08-07 18:44:03', '2026-08-07 18:44:10'),
(208, 120, 'Permintaan Khusus', 'service-items/CoCX7VJ9zPTJlAHhA3qphPqvk2sHLB9PGIl1qOYR.jpeg', '<p>Layanan titip pembelian berdasarkan permintaan jamaah, selama barang tersedia dan memenuhi ketentuan yang berlaku untuk dibawa atau dikirim ke Indonesia.</p>', 3, NULL, NULL, 1, '2026-08-07 18:45:12', '2026-08-14 06:49:45');
