INSERT INTO `settings` (`id`, `logo`, `favicon`, `og_image`, `og_title`, `og_description`, `og_type`, `og_site_name`, `twitter_card`, `twitter_title`, `twitter_description`, `twitter_image`, `canonical_url`, `robots`, `google_site_verification`, `bing_site_verification`, `google_analytics_id`, `google_tag_manager_id`, `schema_enabled`, `org_name`, `org_logo`, `org_phone`, `org_email`, `org_address`, `org_geo_lat`, `org_geo_lng`, `sitemap_enabled`, `banner_image`, `banner_badge`, `banner_title`, `banner_cta_text`, `banner_cta_url`, `hero_subtitle`, `greeting_image`, `greeting_title`, `greeting_subtitle`, `greeting_text`, `why_label`, `why_title`, `why_subtitle`, `about_banner`, `about_image`, `about_title`, `about_body`, `trust_badge_1_icon`, `trust_badge_1_text`, `trust_badge_2_icon`, `trust_badge_2_text`, `trust_badge_3_icon`, `trust_badge_3_text`, `trust_badge_4_icon`, `trust_badge_4_text`, `testimonial_label`, `testimonial_title`, `testimonial_subtitle`, `cta_pill`, `cta_title`, `cta_subtitle`, `cta_button`, `services_page_title`, `services_page_subtitle`, `galeri_page_title`, `galeri_page_subtitle`, `testimoni_page_title`, `testimoni_page_subtitle`, `faq_page_title`, `faq_page_subtitle`, `artikel_page_title`, `artikel_page_subtitle`, `website_name`, `tagline`, `whatsapp`, `wa_message`, `email`, `address`, `footer_text`, `footer_contact_heading`, `footer_links_heading`, `footer_links`, `footer_copyright`, `seo_title`, `seo_description`, `seo_keywords`, `social_instagram`, `social_facebook`, `social_youtube`, `social_tiktok`, `created_at`, `updated_at`) VALUES
(1, 'settings/6LKAECp0CQRlRTwFMAEFWLjpEJzuvHaAHUvxDVEC.webp', 'settings/JES8f7juDQDiQsMEIM2CUgjwMYvjaNzNApTbdgtX.png', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'index, follow', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'settings/Nm83LXikUFXN8w9TOEF9s8ubuODNOhMTyzmZHDNM.webp', NULL, NULL, NULL, NULL, 'Halo', 'settings/aDkXS8czm0NiRg7UBZ7XhbgNkygLpl1g0xDMDrVN.webp', 'Assalamu\'alaikum', 'Selamat datang di Duyufuna', 'Temukan berbagai layanan umroh dan haji untuk menemani perjalanan ibadah Anda dengan lebih mudah, nyaman, dan tenang menuju Tanah Suci.', NULL, NULL, NULL, 'settings/CEKjxYpkH4cmweb57wPUlWFagAp95PVeMr2CDDQZ.jpg', 'settings/Hb985l3DWV3dUoHMM1cYnavXuErjEStvdzK3KSKW.webp', 'DUYUFUNA - Pelayanan Umroh & Haji Profesional', '<h2>Tentang Kami<br><br></h2><p class=\"isSelectedEnd\">Duyufuna hadir sebagai penyedia layanan umroh dan haji yang berkomitmen membantu memenuhi berbagai kebutuhan perjalanan jamaah menuju Tanah Suci. Kami memahami bahwa perjalanan ibadah bukan sekadar perjalanan biasa, tetapi sebuah perjalanan yang membutuhkan persiapan, ketelitian, kenyamanan, dan pelayanan yang baik sejak sebelum keberangkatan hingga jamaah kembali ke tanah air.<br><br></p><p class=\"isSelectedEnd\">Melalui berbagai layanan yang terintegrasi, kami menyediakan kebutuhan pendukung perjalanan seperti pengurusan visa, akomodasi hotel di Mekkah, Madinah, dan Jeddah, transportasi, handling bandara, handling hotel, catering, laundry, serta berbagai kebutuhan lainnya. Setiap layanan disiapkan untuk membantu jamaah maupun penyelenggara perjalanan mendapatkan solusi yang lebih praktis dan terkoordinasi.</p><p class=\"isSelectedEnd\">Kami terus berupaya menghadirkan pelayanan yang responsif, fleksibel, dan berorientasi pada kebutuhan jamaah. Dengan memahami bahwa setiap rombongan memiliki kebutuhan yang berbeda, layanan dapat disesuaikan berdasarkan jumlah jamaah, jadwal perjalanan, pilihan akomodasi, serta kebutuhan khusus lainnya.<br><br></p><h3>Visi</h3><p class=\"isSelectedEnd\">Menjadi penyedia layanan umroh dan haji yang terpercaya dan profesional dalam menghadirkan kemudahan, kenyamanan, serta layanan pendukung perjalanan ibadah yang berkualitas bagi setiap jamaah.<br><br></p><h3>Misi</h3><ul data-spread=\"false\"><li>Menyediakan berbagai layanan pendukung perjalanan umroh dan haji secara lengkap dan terintegrasi.</li><li>Memberikan pelayanan yang mudah, responsif, dan sesuai dengan kebutuhan jamaah.</li><li>Mengutamakan kenyamanan, ketepatan, dan kualitas dalam setiap layanan.</li><li>Membangun kerja sama yang baik dengan berbagai pihak untuk mendukung kelancaran perjalanan jamaah.</li><li>Terus meningkatkan kualitas layanan dan mengikuti perkembangan kebutuhan perjalanan ibadah.</li><li>Membantu menciptakan perjalanan menuju Tanah Suci yang lebih tertata, nyaman, dan tenang bagi jamaah.</li></ul>', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'DUYUFUNA', 'MELAYANI TAMU ALLAH, SEPENUH HATI', NULL, NULL, 'info@duyufuna.com', 'Jepara, Indonesia', '<p>Layanan perjalanan umroh dan haji yang membantu setiap langkah perjalanan menuju Tanah Suci dengan mudah, nyaman, dan terpercaya.</p>', NULL, NULL, NULL, '© 2026 DUYUFUNA', 'DUYUFUNA - Layanan Umroh & Haji Terpercaya', 'Platform layanan umroh, haji, hotel, dan transportasi di tanah suci. Mudah, amanah, berkah.', 'umroh, haji, travel umroh, hotel mekkah, hotel madinah', NULL, NULL, NULL, NULL, '2026-07-28 04:43:27', '2026-08-16 06:34:53');
INSERT INTO `testimonials` (`id`, `name`, `image`, `review`, `rating`, `status`, `created_at`, `updated_at`) VALUES
(1, 'H. Ahmad Fauzi', NULL, 'Pelayanan DUYUFUNA sangat memuaskan, hotel dan catering nya nyaman. Sangat direkomendasikan.', 5, 1, '2026-08-01 20:18:25', '2026-08-01 20:18:25'),
(2, 'Ibu Siti Rahma', NULL, 'Transportasi dan handling bandara lancar, tim ramah dan siap. Perjalanan ibadah kami jadi tenang.', 5, 1, '2026-08-01 20:18:25', '2026-08-01 20:18:25'),
(3, 'Bp. Budi Santoso', NULL, 'Proses visa dan pengurusan dokumen cepat dan jelas. Alhamdulillah puas beribadah ke Tanah Suci.', 4, 1, '2026-08-01 20:18:25', '2026-08-01 20:18:25'),
(4, 'Ibu Asih', NULL, 'Terima kasih DUYUFUNA, semua diurus rapi mulai visa, hotel, sampai transportasi. Ibadah kami jadi tenang.', 5, 1, '2026-08-06 23:53:03', '2026-08-06 23:53:03'),
(5, 'Bp. Dwi Cahyono', NULL, 'Handling dan catering-nya top, petugas ramah. Sangat direkomendasikan untuk keluarga.', 4, 1, '2026-08-06 23:53:03', '2026-08-06 23:53:03');
